import{d as s,C as n,o as g,c as h,E as t,a3 as a}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"临卦","description":"第十九卦·地泽临——泽上有地，教思无穷，容保民无疆。","frontmatter":{"title":"临卦","description":"第十九卦·地泽临——泽上有地，教思无穷，容保民无疆。","category":"hexagram","aliases":["临","地泽临"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-19.md","filePath":"yijing/hexagrams/hexagram-19.md","lastUpdated":1787730063000}'),p={name:"yijing/hexagrams/hexagram-19.md"},b=s({...p,setup(m){const l=[{id:"xianlin",term:"咸临",pinyin:"xián lín",meaning:"以感应而临。咸为无心之感、自然而然，不是「应该走近」，而是本性的自然感应。"},{id:"ganlin",term:"甘临",pinyin:"gān lín",meaning:"以甜、讨好来维持靠近，失去了咸临的本真。"},{id:"zhilin",term:"至临",pinyin:"zhì lín",meaning:"真的到了、亲临。「至」这个动作本身就是答案。"},{id:"zhilin2",term:"知临",pinyin:"zhī lín",meaning:"以知而临，知道自己为何而临——不是「知道怎么做」，是「知道为什么做」。"},{id:"dunlin",term:"敦临",pinyin:"dūn lín",meaning:"敦厚而临，本来的样子。把每一次起心动念都当作自我反思，长久下来敦厚成德。"},{id:"zhixingzheng",term:"志行正",pinyin:"zhì xíng zhèng",meaning:"志向行为端正。咸临贞吉，因志行正——感应先于目的。"},{id:"weishunming",term:"未顺命",pinyin:"wèi shùn mìng",meaning:"不顺从命运。不因现实限制（技术、资源、时机）而止步，在限制中仍然前行。"},{id:"weibudang",term:"位不当",pinyin:"wèi bù dàng",meaning:"位置不当。甘临因位不当——用错的方式靠近。"},{id:"jiubuchang",term:"咎不长",pinyin:"jiù bù cháng",meaning:"过错不会长久。既忧之，咎不长也——觉察是转化的开始。"},{id:"weidang",term:"位当",pinyin:"wèi dàng",meaning:"位置得当。至临无咎，因位当——顺着坤德走到了该在的位置。"},{id:"xingzhong",term:"行中",pinyin:"xíng zhōng",meaning:"行于中道。大君之宜，行中之谓也——柔中而应刚中。"},{id:"zhizainei",term:"志在内",pinyin:"zhì zài nèi",meaning:"志向在内。敦临之吉，志在内也——每一次重新开始的厚度。"}],e=[{position:"初九",type:"yang",text:"咸临，贞吉。",xiang:"咸临贞吉，志行正也。",textModern:"以无心之感而临——不是「应该走近」，而是本性的自然感应。起心动念是真实的，不是表演的，守正则吉。",xiangModern:"咸临而守正吉，因为志向行为端正——感应先于目的，动机是正的。"},{position:"九二",type:"yang",text:"咸临，吉，无不利。",xiang:"咸临吉无不利，未顺命也。",textModern:"已经迈出去、在路上，刚中而应；不因现实限制（技术、资源、时机）而止步，坚守自己的位置，吉，无不利。",xiangModern:"咸临吉无不利，因为「未顺命」——不向命运妥协，在限制中仍然前行。"},{position:"六三",type:"yin",text:"甘临，无攸利。既忧之，无咎。",xiang:"甘临，位不当也。既忧之，咎不长也。",textModern:"用甜、讨好来维持靠近，失去了咸临的本真，没有真正的连接；但若能察觉、反思、忧虑自己的状态，就能无咎。",xiangModern:"甘临是因为位置不当；但既已忧之，过错就不会长久——觉察是转化的开始。"},{position:"六四",type:"yin",text:"至临，无咎。",xiang:"至临无咎，位当也。",textModern:"真的到了，站在岸边，湖面开始映照你，你看见的是自己。「至」本身就是答案——不是因为做对了什么，而是你真的来了。",xiangModern:"至临无咎，因为位置得当——顺着坤德，走到了该在的位置。"},{position:"六五",type:"yin",text:"知临，大君之宜，吉。",xiang:"大君之宜，行中之谓也。",textModern:"知道自己为何而临——不是「知道怎么做」，是「知道为什么做」。照见自己，才能照见他人，这是大君应有的样子。",xiangModern:"大君之宜，在于行于中道——柔中而应九二刚中，不刚强临人，以「知」临人。"},{position:"上六",type:"yin",text:"敦临，吉，无咎。",xiang:"敦临之吉，志在内也。",textModern:"敦厚而临，本来的样子。不是临到头就完了，而是把每一次起心动念都当作咸临、甘临、至临的自我反思，长久下来就做到了敦临。",xiangModern:"敦临之吉，在于志向在内——每一次重新开始的厚度，最终回到问心无愧的无咎。"}];return(u,i)=>{const o=n("DaoHexagramViewer"),r=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return g(),h("div",null,[t(o,{name:"临",fullName:"地泽临",upper:"☷",lower:"☱",guaCi:"临，元亨，利贞。至于八月有凶。",pinyin:["lín"],element:"土",direction:"西南",insight:"地俯临泽，带着感应与德性走近；元亨利贞，八月有凶，知进退。",guaSlug:"19dizelin",lines:e}),i[0]||(i[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>泽上有地，临。君子以教思无穷，容保民无疆。</p><p>上坤为地、下兑为泽，大地俯临湖泽，是「临」之象。君子由此悟到两层：<strong>教思无穷</strong>（兑/泽）——走近他人，让对方在作品、在关系中看见自己的倒影；<strong>容保民无疆</strong>（坤/地）——大地承载湖泽，不控制、不占有，以无边的包容承载万物。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>临，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。至于八月有凶，消不久也。</p><p>逐句释义：</p><ul><li><strong>临，刚浸而长</strong> —— 临卦阳刚渐长（两阳爻在下，阳气上长），生机勃发。</li><li><strong>说而顺</strong> —— 下兑为悦、上坤为顺，悦而顺。</li><li><strong>刚中而应</strong> —— 九二刚健居中，与六五相应。</li><li><strong>大亨以正，天之道也</strong> —— 大亨是因为守正，这是天道。</li><li><strong>至于八月有凶，消不久也</strong> —— 到了八月（阴气盛）有凶，因为阳气的消退不会长久。</li></ul><blockquote><p><strong>至于八月有凶</strong>：临是十二消息卦里的丑月（十二月），阳气上升；八月是观卦，阴气渐盛、潮水将退。圣人的提醒是——整体地看、周期地看，不执着于一时之吉，不恐惧一时之凶。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',9)),t(r,{element:"土",guaSlug:"19dizelin",glossary:l,items:e}),i[1]||(i[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><p>临卦的六爻，可以看成一幅「人走向湖」的空间画面：</p><ul><li>初九：人 —————— 湖（心动了，看见了）</li><li>九二：— 人 ——— 湖（迈出去了，在路上）</li><li>六三：—— 人 —— 湖（走着走着，开始用甜维持）</li><li>六四：———— 人 湖（真的到了，站在岸边）</li><li>六五：（站在岸边，知道自己为何而来）</li><li>上六：（每一次重新开始，厚积成德）</li></ul><h3 id="初九-·-咸临-贞吉" tabindex="-1">初九 · 咸临，贞吉 <a class="header-anchor" href="#初九-·-咸临-贞吉" aria-label="Permalink to &quot;初九 · 咸临，贞吉&quot;">​</a></h3><ul><li><strong>咸</strong>：感应，无心之感，自然而然</li><li>初九以阳爻居初位，是最初的起心动念</li><li>不是因为「应该走近」，而是本性的自然感应</li><li>感应先于目的，起心动念是真实的，不是表演的</li></ul><blockquote><p>咸临的「正」，在于感应先于目的。</p></blockquote><h3 id="九二-·-咸临-吉-无不利" tabindex="-1">九二 · 咸临，吉，无不利 <a class="header-anchor" href="#九二-·-咸临-吉-无不利" aria-label="Permalink to &quot;九二 · 咸临，吉，无不利&quot;">​</a></h3><ul><li>九二以阳爻居二位，刚中，已经迈出去、在路上</li><li><strong>未顺命也</strong>：不因现实的限制（技术、资源、时机）而止步，坚守在自己的位置上</li><li>与六五相应：一刚一柔，一迈出一照见，临卦最美的结构</li></ul><blockquote><p>刚中之道，不是蛮干，是在限制中仍然前行，不向命运妥协。</p></blockquote><h3 id="六三-·-甘临-无攸利。既忧之-无咎" tabindex="-1">六三 · 甘临，无攸利。既忧之，无咎 <a class="header-anchor" href="#六三-·-甘临-无攸利。既忧之-无咎" aria-label="Permalink to &quot;六三 · 甘临，无攸利。既忧之，无咎&quot;">​</a></h3><ul><li><strong>甘</strong>：甜蜜，用讨好、用甜来维持靠近</li><li>六三以阴爻居三位，不当位，走着走着失去了咸临的本真</li><li><strong>无攸利</strong>：这样的靠近，没有真正的利益，也没有真正的连接</li><li><strong>既忧之，无咎</strong>：但若能察觉、反思、忧虑自己的状态，就能无咎</li></ul><blockquote><p>觉察是转化的开始。甘临不是罪，不自知才是问题所在。</p></blockquote><h3 id="六四-·-至临-无咎" tabindex="-1">六四 · 至临，无咎 <a class="header-anchor" href="#六四-·-至临-无咎" aria-label="Permalink to &quot;六四 · 至临，无咎&quot;">​</a></h3><ul><li><strong>至</strong>：真的到了</li><li>六四进入上卦坤，阴爻居阴位，当位，顺着坤德走到了</li><li>「能看到影子的那一刻」：走近到足够近，湖面开始映照你，你看见的是自己</li><li><strong>为何无咎</strong>：不是因为做对了什么，而是因为——你真的来了</li></ul><blockquote><p>至临是行动的完成，是「到」这个动作本身的价值。</p></blockquote><h3 id="六五-·-知临-大君之宜-吉" tabindex="-1">六五 · 知临，大君之宜，吉 <a class="header-anchor" href="#六五-·-知临-大君之宜-吉" aria-label="Permalink to &quot;六五 · 知临，大君之宜，吉&quot;">​</a></h3><ul><li>六五以阴爻居五位，柔中，与九二刚中相应</li><li><strong>知</strong>：知道自己为何而临</li><li>不是「知道怎么做」，是「知道为什么做」；强加的意义是甘临，自然涌现的源头是知临</li><li>六五不以刚强临人，以「知」临人——照见自己，才能照见他人</li></ul><blockquote><p>明明德，不是「懂得道理」，是照亮自己本来就有的德。</p></blockquote><h3 id="上六-·-敦临-吉-无咎" tabindex="-1">上六 · 敦临，吉，无咎 <a class="header-anchor" href="#上六-·-敦临-吉-无咎" aria-label="Permalink to &quot;上六 · 敦临，吉，无咎&quot;">​</a></h3><ul><li><strong>敦</strong>：敦实，厚重，本来的样子（参艮卦「敦艮」）</li><li>上六是临卦的终点，也是新的起点</li><li>把每一次的起心动念，都当作一次咸临、甘临、至临的自我反思，长久下来就做到了敦临</li><li><strong>敦本身为吉</strong>：不是耍机灵、不是偷懒，是每一次走近都带着厚度与反思</li></ul><blockquote><p>敦临不是终点，是每次重新开始的厚度。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',22)),t(d,{title:"字词释义",items:[{term:"临",pinyin:["lín"],meaning:"走近、俯临、亲临。带着感应与德性，主动走近他人、走近事物。"},{term:"咸",pinyin:["xián"],meaning:"感应，无心之感，自然而然。"},{term:"甘临",pinyin:["gān","lín"],meaning:"用甜、讨好来维持靠近，失去本真。"},{term:"至临",pinyin:["zhì","lín"],meaning:"真的到了、亲临。「至」这个动作本身就是答案。"},{term:"知临",pinyin:["zhī","lín"],meaning:"知道自己为何而临——知道为什么做。"},{term:"敦临",pinyin:["dūn","lín"],meaning:"敦厚而临，本来的样子。"},{term:"元亨",pinyin:["yuán","hēng"],meaning:"大通。阳气上升，万物将临，生机勃发。"},{term:"利贞",pinyin:["lì","zhēn"],meaning:"利于守正，不是利于得利。"},{term:"教思无穷",pinyin:["jiào","sī","wú","qióng"],meaning:"教化思虑无穷（兑/泽），让对方看见自己的倒影。"},{term:"容保民无疆",pinyin:["róng","bǎo","mín","wú","jiāng"],meaning:"包容保育民众无疆（坤/地），以无边的包容承载万物。"}]}),i[2]||(i[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>临卦讲的是<strong>走近与俯临</strong>。上坤（地）下兑（泽），地在上、泽在下，大地俯临湖泽。</p><p>卦辞「元亨，利贞，至于八月有凶」点明：大通、利于守正，但圣人提醒八月（观卦）潮水将退，要整体地、周期地看待吉凶。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>临，不是居高临下的控制，而是带着感应、带着德性，主动走近他人、走近事物。</p><p>六爻是「走近」的六种状态：咸临（感应）、甘临（讨好）、至临（到了）、知临（知为何）、敦临（敦厚）——每一种，都对应人生里一次「靠近」的质量。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>感应先于目的：起心动念要真实，不表演（初九咸临）</li><li>在限制中前行：不向命运妥协（九二未顺命）</li><li>觉察是转化的开始：甘临不可怕，不自知才可怕（六三）</li><li>到本身就是答案：真的走近，比做对什么更重要（六四）</li><li>知道为何而作：照亮自己本来就有的德（六五知临）</li><li>每次重新开始的厚度：长久反思，敦厚成德（上六敦临）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻完整画面：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞</th><th>画面</th><th>核心</th></tr></thead><tbody><tr><td>初九</td><td>咸临，贞吉</td><td>心动，起念，开始靠近</td><td>本性感应，先于目的</td></tr><tr><td>九二</td><td>咸临，吉，无不利</td><td>迈出去，在路上</td><td>刚中，未顺命</td></tr><tr><td>六三</td><td>甘临，无攸利，既忧之无咎</td><td>用甜维持，察觉反思</td><td>觉察是转化的开始</td></tr><tr><td>六四</td><td>至临，无咎</td><td>站在岸边，看见倒影</td><td>到，本身就是答案</td></tr><tr><td>六五</td><td>知临，大君之宜，吉</td><td>知道为何而来</td><td>明明德，知行合一</td></tr><tr><td>上六</td><td>敦临，吉，无咎</td><td>每次重新开始的厚度</td><td>长久反思，敦厚成德</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>咸临</strong>——感应先于目的，起心动念真实不表演</li><li><strong>九二刚中</strong>——未顺命，在限制中仍前行，不向命运妥协</li><li><strong>甘临</strong>——觉察是转化的开始，不自知才是问题</li><li><strong>至临</strong>——「到」本身就是答案，真的来了才看见自己</li><li><strong>知临</strong>——明明德，照亮自己本来就有的德</li><li><strong>敦临</strong>——敦临不是终点，是每次重新开始的厚度</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>临卦与「薪火修行」的呼应：</p><ul><li><strong>咸临</strong>：洞见「二进制即阴阳」，是最初的感应，先于弘扬的志向，是为「正」</li><li><strong>九二刚中</strong>：在技术、资源等现实限制下，坚守「易理与代码交叉点」这一稀缺位置，未顺命也</li><li><strong>知临</strong>：创作「薪火」，不是为了宏大叙事，而是知道自己为何而作——帮故事把自己长出来</li><li><strong>敦临</strong>：以代码入道，每一次实践都是一次咸临的重新开始，长久下去，敦厚成德</li></ul><p><strong>一句话收整卦</strong>：</p><p>临，不是居高临下，是带着德性，一次次走近——照见自己，照见他人，照见整体。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：观（第二十卦）、泰（第十一卦）</li><li>临与观：俯临与仰观，是一对——你走近，也要知道退；你临，也要能观</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',21))])}}});export{x as __pageData,b as default};
